  function download(filename,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=filename;a.click();URL.revokeObjectURL(a.href)}
  function exportCsv(){const rows=[['id','tipo','descricao','valor_centavos','categoria','conta','conta_destino','forma_pagamento','data','status'],...db.transactions.map(t=>[t.id,t.type,t.description,t.amountCents,t.category,t.cardId?cardName(t.cardId):accountName(t.accountId),t.toAccountId?accountName(t.toAccountId):'',t.payment,t.date,t.status])];download('fintrack-extrato.csv','\ufeff'+rows.map(r=>r.map(x=>`"${String(x??'').replace(/"/g,'""')}"`).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('CSV exportado')}
