  function parseCsv(text){const rows=[];let row=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){value+='"';i++}else if(c==='"'){quoted=!quoted}else if(c===';'&&!quoted){row.push(value);value=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x!==''))rows.push(row);row=[];value=''}else value+=c}if(value||row.length){row.push(value);rows.push(row)}return rows}
  el('#csvImport').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const rows=parseCsv((await file.text()).replace(/^\ufeff/,''));const header=rows.shift()?.map(x=>x.trim());const required=['id','tipo','descricao','valor_centavos','categoria','conta','conta_destino','forma_pagamento','data','status'];if(!header||required.some(k=>!header.includes(k)))throw new Error('CSV não tem o formato exportado pelo FinTrack.');const index=Object.fromEntries(required.map(k=>[k,header.indexOf(k)]));const knownIds=new Set(db.transactions.map(t=>t.id));const signatures=new Set(db.transactions.map(t=>`${t.type}|${t.description}|${t.date}|${t.amountCents}`));const accountByName=new Map(db.accounts.map(a=>[a.name,a.id]));const imported=[],issues=[],duplicates=[];for(const [line,r] of rows.entries()){const t={id:r[index.id],type:r[index.tipo],description:r[index.descricao],amountCents:Number(r[index.valor_centavos]),category:r[index.categoria],accountId:accountByName.get(r[index.conta]),toAccountId:r[index.conta_destino]?accountByName.get(r[index.conta_destino]):null,payment:r[index.forma_pagamento],date:r[index.data],status:r[index.status]};const validation=validateTransaction(t,new Set(db.accounts.map(a=>a.id)));if(validation){issues.push(`linha ${line+2}: ${validation}`);continue}const signature=`${t.type}|${t.description}|${t.date}|${t.amountCents}`;if(knownIds.has(t.id)||signatures.has(signature)){duplicates.push(line+2);continue}knownIds.add(t.id);signatures.add(signature);imported.push(t)}if(issues.length){alert(`${issues.length} linha(s) inválida(s); nenhuma alteração feita.\n${issues.slice(0,5).join('\n')}`);return}if(!imported.length){toast(duplicates.length?`${duplicates.length} duplicata(s) ignorada(s)`:'Nenhuma linha válida para importar');return}if(!confirm(`${imported.length} movimentação(ões) pronta(s) para importar. ${duplicates.length} duplicata(s) serão ignoradas. Continuar?`))return;db.transactions.push(...imported);for(const t of imported)if(t.category&&!db.categories.includes(t.category))db.categories.push(t.category);save();toast(`${imported.length} movimentação(ões) importada(s)`)}catch(err){alert(`Importação não concluída: ${err.message}`)}finally{e.target.value=''}});
  document.addEventListener('change',async e=>{if(e.target.id!=='profilePhoto')return;const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Selecione um arquivo de imagem');return}if(file.size>10*1024*1024){toast('A imagem deve ter no máximo 10 MB');return}try{const bitmap=await createImageBitmap(file),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);db.profile.avatarDataUrl=canvas.toDataURL('image/jpeg',.82);save();toast('Foto de perfil atualizada')}catch{toast('Não foi possível carregar a imagem')}finally{e.target.value=''}});
